public static class SeolpyeongFaceSetup{
 const string R="LocalArchive/SeolpyeongFace20261019",D="Assets/Art/Characters/SeolpyeongFace20261019",MeshPath="Assets/Art/Characters/Parts20261018/Seolpyeong/Parts_Game.asset",Prefab="Assets/Art/Characters/Parts20261018/Seolpyeong/Visual.prefab";
 [Serializable]public class Entry{public string part,@base,normal,metalSmooth;public float roughness;public bool alphaClip;}[Serializable]class Catalog{public Entry[] items;}
 static Transform Visual()=>Object.FindObjectsByType<Transform>(FindObjectsInactive.Include).Single(t=>t.name=="Seolpyeong"&&t.Find("VarcoVisual")).Find("VarcoVisual");
 static string State(Transform root)=>string.Join("\n",root.GetComponents<Component>().Select(x=>EditorJsonUtility.ToJson(x)))+string.Join("\n",root.GetComponentsInChildren<Collider>(true).Select(x=>EditorJsonUtility.ToJson(x)));
 static Material Mat(Entry e){string p=D+"/"+e.part+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find(e.part=="Groom"?"RedCliffs/Character Hair":"Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.shader=Shader.Find(e.part=="Eyes"?"RedCliffs/Character Eye":e.part=="Groom"?"RedCliffs/Character Hair":"Universal Render Pipeline/Lit");foreach(var item in new[]{(e.@base,"_BaseMap"),(e.normal,"_BumpMap"),(e.metalSmooth,"_MetallicGlossMap")}){if(string.IsNullOrEmpty(item.Item1)){m.SetTexture(item.Item2,null);continue;}string path=D+"/"+item.Item1;var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=item.Item2=="_BumpMap"?TextureImporterType.NormalMap:TextureImporterType.Default;imp.sRGBTexture=item.Item2=="_BaseMap";imp.maxTextureSize=2048;imp.mipmapEnabled=true;imp.textureCompression=TextureImporterCompression.CompressedHQ;if(e.alphaClip&&item.Item2=="_BaseMap")imp.alphaIsTransparency=true;imp.SaveAndReimport();m.SetTexture(item.Item2,AssetDatabase.LoadAssetAtPath<Texture2D>(path));}m.SetColor("_BaseColor",Color.white);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",string.IsNullOrEmpty(e.metalSmooth)?1-e.roughness:1);m.SetFloat("_BumpScale",1);if(string.IsNullOrEmpty(e.normal))m.DisableKeyword("_NORMALMAP");else m.EnableKeyword("_NORMALMAP");if(string.IsNullOrEmpty(e.metalSmooth))m.DisableKeyword("_METALLICSPECGLOSSMAP");else m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Surface",0);m.SetFloat("_ZWrite",1);m.SetFloat("_Cull",e.part=="Groom"?0:2);m.SetFloat("_AlphaClip",e.alphaClip?1:0);m.SetFloat("_Cutoff",.45f);m.SetFloat("_AlphaToMask",e.alphaClip?1:0);if(e.alphaClip){m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;m.SetOverrideTag("RenderType","TransparentCutout");}else{m.DisableKeyword("_ALPHATEST_ON");m.renderQueue=-1;}if(e.part=="Groom"){m.SetFloat("_SpecularStrength",.025f);m.SetShaderPassEnabled("ShadowCaster",false);}if(e.part=="Eyes"){m.SetFloat("_EnvironmentReflections",0);m.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");m.SetFloat("_ScreenSpaceReflections",0);m.SetFloat("_ScreenSpaceReflectionsContributeTransparent",0);m.SetFloat("_Smoothness",.62f);m.SetFloat("_SpecularStrength",.02f);}EditorUtility.SetDirty(m);return m;}
 [MenuItem("Tools/RedCliffs/Seolpyeong Face/Import Baked Face")]public static void Import(){if(EditorApplication.isPlaying)throw new Exception("Exit Play first");var entries=JsonUtility.FromJson<Catalog>("{\"items\":"+File.ReadAllText(R+"/GameExport/materials.json")+"}").items;Directory.CreateDirectory(D);var files=new HashSet<string>{"Seolpyeong_Face.fbx"};foreach(var e in entries)foreach(var f in new[]{e.@base,e.normal,e.metalSmooth})if(!string.IsNullOrEmpty(f))files.Add(f);foreach(var f in files)if(!File.Exists(R+"/GameExport/"+f))throw new Exception("Missing bake "+f);AssetDatabase.DisallowAutoRefresh();try{foreach(var f in files)File.Copy(R+"/GameExport/"+f,D+"/"+f,true);File.WriteAllText(D+"/.gitattributes","*.fbx -filter -diff -merge -text\n*.png -filter -diff -merge -text\n*.mat -filter -diff -merge\n");}finally{AssetDatabase.AllowAutoRefresh();}AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(D+"/Seolpyeong_Face.fbx");importer.isReadable=true;importer.importAnimation=false;importer.importBlendShapes=false;importer.SaveAndReimport();var map=entries.ToDictionary(e=>e.part,Mat);var tmp=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Seolpyeong_Face.fbx"));try{var filters=tmp.GetComponentsInChildren<MeshFilter>().OrderBy(x=>x.name).ToArray();var list=filters.Select(x=>new CombineInstance{mesh=x.sharedMesh,transform=x.transform.localToWorldMatrix}).ToArray();var combined=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,name="Seolpyeong_FaceRefined_Game"};combined.CombineMeshes(list,false,true);if(combined.bounds.size.y<1.65f||combined.bounds.size.y>1.75f)throw new Exception("Scale/axis mismatch "+combined.bounds);var v=Visual();string state=State(v.parent),motion=EditorJsonUtility.ToJson(v.GetComponent<RedCliffMystery.VarcoIdleMotion>());var model=v.Find("Model");var saved=AssetDatabase.LoadAssetAtPath<Mesh>(MeshPath);if(!saved)throw new Exception("Preserve existing