 [MenuItem("Tools/RedCliffs/Seolpyeong Face/Inspect")]public static void Inspect(){var model=Visual().Find("Model");var mesh=model.GetComponent<MeshFilter>().sharedMesh;var materials=model.GetComponent<Renderer>().sharedMaterials;var errors=new List<string>();if(mesh.subMeshCount!=materials.Length)errors.Add("Material count mismatch");if(mesh.uv.Length!=mesh.vertexCount)errors.Add("Missing UV0");foreach(var m in materials){if(!m||!m.GetTexture("_BaseMap"))errors.Add("Missing map");if(m&&(!m.shader.isSupported||ShaderUtil.GetShaderMessages(m.shader).Any(x=>x.severity.ToString()=="Error")))errors.Add("Shader failure");}var deps=AssetDatabase.GetDependencies(Prefab,true);if(deps.Any(x=>x.Contains("EnemiesHair")||x.Contains("EnemiesGroom")))errors.Add("Retired Enemies hair dependency");File.WriteAllText(R+"/inspection.txt","Vertices="+mesh.vertexCount+"\nSubmeshes="+mesh.subMeshCount+"\nMaterials="+string.Join(",",materials.Select(x=>x.name))+"\nErrors="+string.Join(";",errors));if(errors.Count>0)throw new Exception(string.Join(";",errors));}
 [MenuItem("Tools/RedCliffs/Seolpyeong Face/Capture Static Face")]public static void Capture(){if(EditorApplication.isPlaying)throw new Exception("Static check after Play");var v=Visual();var go=new GameObject("Seol temporary static check"){hideFlags=HideFlags.HideAndDontSave};var rt=new RenderTexture(1920,1080,24);var previous=RenderTexture.active;Texture2D image=null;try{var cam=go.AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.enabled=false;cam.targetTexture=rt;cam.fieldOfView=36;cam.aspect=16f/9;cam.nearClipPlane=.03f;var aim=v.TransformPoint(new Vector3(0,1.53f,0));cam.transform.position=aim+v.TransformDirection(new Vector3(.08f,.02f,-.65f));cam.transform.LookAt(aim);cam.Render();RenderTexture.active=rt;image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(R+"/static-face.png",image.EncodeToPNG());}finally{RenderTexture.active=previous;if(image)Object.DestroyImmediate(image);Object.DestroyImmediate(go);rt.Release();Object.DestroyImmediate(rt);}}
